package main

import "testing"

func TestTables(t *testing.T) {
	cases := []struct {
		players int
		want    int
	}{
		{0, 0},
		{1, 0},
		{2, 1},
		{9, 1},
		{10, 2},
		{19, 3},
	}
	for _, c := range cases {
		if got := tables(c.players); got != c.want {
			t.Errorf("tables(%d) = %d, want %d", c.players, got, c.want)
		}
	}
}

