package main

import "testing"

func TestPen(t *testing.T) {
	cases := []struct {
		name    string
		minutes int
		want    string
	}{
		{"no prediction", 0, ""},
		{"negative prediction", -5, ""},
		{"fast runner", 150, "A"},
		{"exactly three hours", 180, "A"},
		{"steady runner", 200, "B"},
		{"exactly four hours", 240, "B"},
		{"walker", 300, "C"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := pen(c.minutes); got != c.want {
				t.Errorf("pen(%d) = %q, want %q", c.minutes, got, c.want)
			}
		})
	}
}

