question.answer:
package main

import (
	"errors"
	"math"
	"strconv"
	"testing"
)

func TestAtoiValues(t *testing.T) {
	cases := []struct {
		in   string
		want int
	}{
		{"42", 42},
		{"+7", 7},
		{"-7", -7},
		{"0", 0},
		{"007", 7},
		{"9223372036854775807", math.MaxInt},
		{"-9223372036854775808", math.MinInt},
	}
	for _, c := range cases {
		got, err := atoi(c.in)
		if err != nil {
			t.Errorf("atoi(%q) returned error %v", c.in, err)
			continue
		}
		if got != c.want {
			t.Errorf("atoi(%q) = %d, want %d", c.in, got, c.want)
		}
	}
}

func TestAtoiErrors(t *testing.T) {
	cases := []struct {
		in      string
		want    int
		wantErr error
	}{
		{"", 0, strconv.ErrSyntax},
		{"-", 0, strconv.ErrSyntax},
		{"abc", 0, strconv.ErrSyntax},
		{"12a", 0, strconv.ErrSyntax},
		{" 12 ", 0, strconv.ErrSyntax},
		{"9223372036854775808", math.MaxInt, strconv.ErrRange},
		{"-9223372036854775809", math.MinInt, strconv.ErrRange},
	}
	for _, c := range cases {
		got, err := atoi(c.in)
		if !errors.Is(err, c.wantErr) {
			t.Errorf("atoi(%q) error = %v, want %v", c.in, err, c.wantErr)
			continue
		}
		if got != c.want {
			t.Errorf("atoi(%q) = %d, want %d", c.in, got, c.want)
		}
	}
}

extra.text:
package main

import (
	"math"
	"strconv"
)

func atoi(s string) (int, error) {
	syntax := &strconv.NumError{Func: "Atoi", Num: s, Err: strconv.ErrSyntax}
	if s == "" {
		return 0, syntax
	}
	neg := false
	digits := s
	if s[0] == '+' || s[0] == '-' {
		neg = s[0] == '-'
		digits = s[1:]
	}
	if digits == "" {
		return 0, syntax
	}
	outOfRange := func() (int, error) {
		err := &strconv.NumError{Func: "Atoi", Num: s, Err: strconv.ErrRange}
		if neg {
			return math.MinInt, err
		}
		return math.MaxInt, err
	}
	const maxU = math.MaxUint64
	const cutoff = maxU/10 + 1
	var n uint64
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		if c < '0' || c > '9' {
			return 0, syntax
		}
		if n >= cutoff {
			return outOfRange()
		}
		n *= 10
		n1 := n + uint64(c-'0')
		if n1 < n {
			return outOfRange()
		}
		n = n1
	}
	const half = uint64(math.MaxInt) + 1
	if !neg && n >= half {
		return outOfRange()
	}
	if neg && n > half {
		return outOfRange()
	}
	v := int(n)
	if neg {
		v = -v
	}
	return v, nil
}

