		return 0, syntax
	}
	outOfRange := func() (int, error) {
		err := &strconv.NumError{Func: "Atoi", Num: s, Err: strconv.ErrRange}
		if neg {
			return math.MinInt, err
		}
		return math.MaxInt, err
	}
	const maxU = math.MaxUint64
	const cutoff = maxU/10 + 1
	var n uint64
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		if c < '0' || c > '9' {
			return 0, syntax
		}
		if n >= cutoff {
			return outOfRange()
		}
		n *= 10
		n1 := n + uint64(c-'0')
		if n1 < n {
			return outOfRange()
		}
		n = n1
	}
	const half = uint64(math.MaxInt) + 1
	if !neg && n >= half {
		return outOfRange()
	}
	if neg && n > half {
		return outOfRange()
	}
	v := int(n)
	if neg {
		v = -v
	}
	return v, nil
}

