package main

import (
	"math"
	"strconv"
)

func atoi(s string) (int, error) {
	syntax := &strconv.NumError{Func: "Atoi", Num: s, Err: strconv.ErrSyntax}
	if s == "" {
		return 0, syntax
	}
	neg := false
	digits := s
	if s[0] == '+' || s[0] == '-' {
		neg = s[0] == '-'
		digits = s[1:]
	}
	if digits == "" {
		return 0, syntax
	}
	outOfRange := func() (int, error) {
		err := &strconv.NumError{Func: "Atoi", Num: s, Err: strconv.ErrRange}
		if neg {
			return math.MinInt, err
		}
		return math.MaxInt, err
	}
	const maxU = math.MaxUint64
	const cutoff = maxU/10 + 1
	var n uint64
	consumed := 0
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		if c < '0' || c > '9' {
			break
		}
		consumed++
		if n >= cutoff {
			return outOfRange()
		}
		n *= 10
		n1 := n + uint64(c-'0')
		if n1 < n {
			return outOfRange()
		}
		n = n1
	}
	if consumed == 0 {
		return 0, syntax
	}
	const half = uint64(math.MaxInt) + 1
	if !neg && n >= half {
		return outOfRange()
	}
	if neg && n > half {
		return outOfRange()
	}
	v := int(n)
	if neg {
		v = -v
	}
	return v, nil
}

