func atoi(s string) (int, error) {
	syntax := &strconv.NumError{Func: "Atoi", Num: s, Err: strconv.ErrSyntax}
	if s == "" {
		return 0, syntax
	}
	neg := false
	digits := s
	if s[0] == '+' || s[0] == '-' {
		neg = s[0] == '-'
		digits = s[1:]
	}
	if digits == "" {
		return 0, syntax
	}
	n := 0
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		if c < '0' || c > '9' {
			return 0, syntax
		}
		n = n*10 + int(c-'0')
	}
	if neg {
		n = -n
	}
	return n, nil
}

